bash cd paper && python3 - <<'EOF'
import re,glob
for f in sorted(glob.glob('**/*.tex',recursive=True)):
    s=open(f,encoding='utf-8').read()
    for m in re.finditer(r'\\cite\{',s):
        prev=s[m.start()-1] if m.start()>0 else ''
        if prev!='~':
            line=s[:m.start()].count('\n')+1
            print(f"{f}:{line}: prev={prev!r} context={s[max(0,m.start()-25):m.start()+40]!r}")
EOF
